            v_chunk_id,
            v_document_id,
            1,
            $ORIG$המטרה היא לעזור לעובד החדש:  להכיר את הצוות והאנשים בחברה  להבין איך דברים עובדים אצלנו ביום-יום  להרגיש בנוח לשאול שאלות  להשתלב חברתית ומקצועית  חשוב לציין:ה-Buddy לא מחליף את המנהל הישיר או את ההכשרה המקצועית. דברים שמומלץ לעשות  יום לפני ההצטרפות  ליצור קשר עם העובד החדש (רצוי בשעות הבוקר). להציג את עצמך כ-Buddy שלו. לוודא שהוא יודע כיצד להגיע למשרד ביום הראשון. לבדוק אם יש לו שאלות לקראת תחילת העבודה.$ORIG$,
            md5('המטרה היא לעזור לעובד החדש:  להכיר את הצוות והאנשים בחברה  להבין איך דברים עובדים אצלנו ביום-יום  להרגיש בנוח לשאול שאלות  להשתלב חברתית ומקצועית  חשוב לציין:ה-Buddy לא מחליף את המנהל הישיר או את ההכשרה המקצועית. דברים שמומלץ לעשות  יום לפני ההצטרפות  ליצור קשר עם העובד החדש (רצוי בשעות הבוקר). להציג את עצמך כ-Buddy שלו. לוודא שהוא יודע כיצד להגיע למשרד ביום הראשון. לבדוק אם יש לו שאלות לקראת תחילת העבודה.'),
            'text'::chunks_content_type_enum,
            NULL,
            409,
            69,
            '{"parser": "legacy-migration", "file_name": "jeen buddy guidelines general.docx", "file_type": "docx", "legacyData": {"legacy_id": "40b3ebb9-e4d6-4d36-9f6d-f857fb518c58", "external_id": null, "collection": "collection", "type": "chunk-data", "tags": "", "user_id": "306916b02924f0142a236cc978b0d013", "create_date": "2026-03-15T07:09:53.895Z", "link_to_file": "https://jeenfilesdevweu.blob.core.windows.net/jeendocs/306916b02924f0142a236cc978b0d013/data/1773558588708-jeen buddy guidelines general.docx", "excerptKeywords": "KEYWORDS: עובד חדש, צוות, Buddy, השתלבות, שאלות"}}'::jsonb,
            '2026-03-15T07:09:53.895000+00:00',
            $TRANS$The goal is to help the new employee: get to know the staff and people in the company Understand how things work for us on a daily basis Feel comfortable asking questions Integrate socially and professionally It is important to note: The Buddy does not replace the direct manager or the professional training. Things to do the day before joining contact with the new employee (preferably in the morning). Introduce yourself as his Buddy. Make sure he knows how to get to the office on the first day. Check if he has any questions before starting work.$TRANS$
        );
    END IF;
END $chunk_fn$;


